function isValid(date: unknown): boolean {
  return !((!isDate(date) && typeof date !== "number") || isNaN(+toDate(date)));
}

function isWednesday(
  date: DateArg<Date> & {},
  options?: IsWednesdayOptions | undefined,
): boolean {
