function tpIsSaturday(date: Temporal.ZonedDateTime): boolean {
  return date.dayOfWeek === 6;
}

function tpIsSunday(date: Temporal.ZonedDateTime): boolean {
  return date.dayOfWeek === 7;
}

function tpIsWeekend(date: Temporal.ZonedDateTime): boolean {
  return tpIsSaturday(date) || tpIsSunday(date);
}

function isConstructor(
  constructor: unknown,
): constructor is GenericDateConstructor {
  return (
    typeof constructor === "function" &&
    constructor.prototype?.constructor === constructor
  );
}

function transpose<InputDate extends Date, ResultDate extends Date>(
  date: InputDate,
  constructor:
    | ResultDate
    | GenericDateConstructor<ResultDate>
    | ContextFn<ResultDate>,
): ResultDate {
  const date_ = isConstructor(constructor)
    ? new constructor(0)
    : constructFrom(constructor, 0);
  date_.setFullYear(date.getFullYear(), date.getMonth(), date.getDate());
  date_.setHours(
    date.getHours(),
    date.getMinutes(),
    date.getSeconds(),
    date.getMilliseconds(),
  );
  return date_;
}

function weeksToDays(weeks: number): number {
  return Math.trunc(weeks * daysInWeek);
}

function yearsToDays(years: number): number {
  return Math.trunc(years * daysInYear);
}

function yearsToMonths(years: number): number {
  return Math.trunc(years * monthsInYear);
}

function yearsToQuarters(years: number): number {
  return Math.trunc(years * quartersInYear);
}
